1	package net.officefloor.hq.app.claim;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.List;
7	import net.officefloor.hq.app.Audit;
8	import net.officefloor.hq.app.period.Period;
9	import net.officefloor.hq.app.period.PeriodClosedException;
10	import net.officefloor.hq.app.period.PeriodRepository;
11	import net.officefloor.hq.app.person.Person;
12	import net.officefloor.hq.app.person.PersonNotFoundException;
13	import net.officefloor.hq.app.person.PersonRetiredException;
14	import net.officefloor.hq.app.person.PersonRepository;
15	import net.officefloor.hq.app.rate.Rate;
16	import net.officefloor.hq.app.rate.RateService;
17	import net.officefloor.hq.app.rollup.RollupService;
18	import net.officefloor.hq.app.setting.Role;
19	import net.officefloor.hq.app.setting.SettingService;
20	import net.officefloor.hq.app.sheet.Sheet;
21	import net.officefloor.hq.app.sheet.SheetService;
22	import org.springframework.stereotype.Service;
23	import org.springframework.transaction.annotation.Transactional;
24	
25	/**
26	 * The claims on a sheet: listed newest first, added to a person and edited one at a time. A claim
27	 * given no date takes the sheet's today. Its due-by is fixed when it is added: its date plus the terms
28	 * in force on that date of its person's grade then (else the sheet's terms in force on it); it does not
29	 * move when its date or the terms change later. A claim is added as DRAFT and moves through its statuses
30	 * as {@link ClaimStatus} allows; a change it does not allow is refused. Opening a claim gives it
31	 * the sheet's next number (or, while the sheet numbers by period, the next within its period), which it
32	 * keeps when voided and is never given again. Only a DRAFT claim
33	 * can be edited; an OPEN one is changed by voiding it and adding a new one. Settling it
34	 * fixes its due at its figure (the due bound by a statement, else its person's grade rate of the
35	 * moment on the claim's date) with its late charge of the moment frozen in; with no figure it
36	 * stays live. A steward can re-settle a SETTLED claim at the figure it would have today as an open claim
37	 * bound by no statement. The user who opened a claim cannot settle it, and a clerk cannot settle one whose
38	 * due is above the sheet's clerk limit (a steward can). No claim dated inside a closed period can
39	 * be added, edited (to or from such a date), opened, settled, re-settled or voided. No claim can be added
40	 * or edited to a date after its person's retirement date. A claim with a negative amount is a
41	 * correction: it must name, by number, a SETTLED claim of the same person; only a correction may name one.
42	 */
43	@Service
44	public class ClaimService {
45	
46	    private final ClaimRepository claims;
47	    private final PersonRepository people;
48	    private final RateService rates;
49	    private final SheetService sheets;
50	    private final RollupService rollup;
51	    private final PeriodRepository periods;
52	    private final SettingService settings;
53	    private final Audit audit;
54	
55	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
56	            RollupService rollup, PeriodRepository periods, SettingService settings, Audit audit) {
57	        this.settings = settings;
58	        this.periods = periods;
59	        this.claims = claims;
60	        this.people = people;
61	        this.rates = rates;
62	        this.sheets = sheets;
63	        this.rollup = rollup;
64	        this.audit = audit;
65	    }
66	
67	    @Transactional(readOnly = true)
68	    public List<Claim> list(String sheetId) {
69	        return claims.findBySheetIdOrderByListedDesc(sheetId);
70	    }
71	
72	    @Transactional
73	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
74	            String corrects) {
75	        // The snapshot locks the sheet first, so the person is read as retired by any retirement before.
76	        RollupService.Snapshot before = rollup.snapshot(sheetId);
77	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
78	        LocalDate on = dateOrToday(sheetId, date);
79	        refuseIfClosed(sheetId, on);
80	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
81	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
82	        LocalDate dueBy = on.plusDays(settings.termsFor(sheetId, person.gradeOn(on), on));
83	        Claim draft = new Claim(sheetId, personId, amount, on, note, dueBy);
84	        draft.setCorrects(corrects);
85	        Claim claim = claims.saveAndFlush(draft);
86	        logStatus(sheetId, user, person, claim);
87	        claim = claims.saveAndFlush(claim);
88	        record("CLAIM_ADDED", sheetId, user, person, claim);
89	        rollup.recordChanges(sheetId, user, before);
90	        return claim;
91	    }
92	
93	    @Transactional
94	    public Claim edit(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
95	            String corrects) {
96	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
97	        if (claim.getStatus() != ClaimStatus.DRAFT) {
98	            throw new ClaimStatusRefusedException();
99	        }
100	        RollupService.Snapshot before = rollup.snapshot(sheetId);
101	        LocalDate on = dateOrToday(sheetId, date);
102	        refuseIfClosed(sheetId, claim.getDate());
103	        refuseIfClosed(sheetId, on);
104	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
105	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
106	        refuseUnlessCorrects(sheetId, person.getId(), amount, corrects);
107	        claim.setAmount(amount);
108	        claim.setCorrects(corrects);
109	        claim.setDate(on);
110	        claim.setNote(note);
111	        Claim saved = claims.saveAndFlush(claim);
112	        record("CLAIM_EDITED", sheetId, user, person, saved);
113	        rollup.recordChanges(sheetId, user, before);
114	        return saved;
115	    }
116	
117	    @Transactional
118	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next) {
119	        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
120	        // once no other open on the sheet is under way; a refusal rolls the number back.
121	        Sheet numbering = next == ClaimStatus.OPEN ? sheets.lockForNumbering(sheetId) : null;
122	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
123	        if (!claim.getStatus().canBecome(next)) {
124	            throw new ClaimStatusRefusedException();
125	        }
126	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
127	            throw new ClaimDeferredException();
128	        }
129	        if (next == ClaimStatus.SETTLED && user.strip().equals(claim.getOpenedBy())) {
130	            throw new ClaimSettledByOpenerException();
131	        }
132	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
133	        // Settling freezes the late charge of the moment into the settled due.
134	        BigDecimal settling = next == ClaimStatus.SETTLED ? chargedFigureOf(sheetId, person, claim) : null;
135	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settling)) next = ClaimStatus.PENDING;
136	        RollupService.Snapshot before = rollup.snapshot(sheetId);
137	        refuseIfClosed(sheetId, claim.getDate());
138	        switch (next) {
139	            case OPEN -> {
140	                number(numbering, claim);
141	                claim.setOpenedBy(user.strip());
142	            }
143	            case SETTLED -> claim.setSettledDue(settling);
144	            default -> {}
145	        }
146	        claim.setStatus(next);
147	        logStatus(sheetId, user, person, claim);
148	        Claim saved = claims.saveAndFlush(claim);
149	        String event = switch (next) {
150	            case OPEN -> "CLAIM_OPENED";
151	            case PENDING -> "CLAIM_PENDING";
152	            case SETTLED -> "CLAIM_SETTLED";
153	            case VOID -> "CLAIM_VOIDED";
154	            case DRAFT -> throw new IllegalStateException();
155	        };
156	        String due = next == ClaimStatus.SETTLED
157	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
158	                : "";
159	        record(event, sheetId, user, person, saved, saved.getNumber(), due);
160	        rollup.recordChanges(sheetId, user, before);
161	        return saved;
162	    }
163	
164	    /** A steward other than its opener approves a PENDING claim: SETTLED, its due fixed at its live due now. */
165	    @Transactional
166	    public Claim approve(String sheetId, String user, Long id) {
167	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
168	        RollupService.Snapshot before = rollup.snapshot(sheetId);
169	        Claim claim = pendingForSteward(sheetId, user, id);
170	        if (user.strip().equals(claim.getOpenedBy())) throw new ClaimApprovedByOpenerException();
171	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
172	        refuseIfClosed(sheetId, claim.getDate());
173	        claim.setSettledDue(chargedFigureOf(sheetId, person, claim));
174	        claim.setStatus(ClaimStatus.SETTLED);
175	        logStatus(sheetId, user, person, claim);
176	        Claim saved = claims.saveAndFlush(claim);
177	        record("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(), " due="
178	                + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString()));
179	        rollup.recordChanges(sheetId, user, before);
180	        return saved;
181	    }
182	
183	    /** A steward rejects a PENDING claim with a reason: OPEN again, bound by its person's last statement if it was. */
184	    @Transactional
185	    public Claim reject(String sheetId, String user, Long id, String reason) {
186	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
187	        RollupService.Snapshot before = rollup.snapshot(sheetId);
188	        Claim claim = pendingForSteward(sheetId, user, id);
189	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
190	        refuseIfClosed(sheetId, claim.getDate());
191	        claim.setStatus(ClaimStatus.OPEN);
192	        logStatus(sheetId, user, person, claim);
193	        Claim saved = claims.saveAndFlush(claim);
194	        record("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber(), " reason=" + reason);
195	        rollup.recordChanges(sheetId, user, before);
196	        return saved;
197	    }
198	
199	    /**
200	     * A steward re-settles a SETTLED claim: its due fixed again at the figure it would have today as an
201	     * open claim bound by no statement (the rate, grade, floor and late percent in force on its date, the
202	     * late charge as of today). Refused for anyone
203	     * else, a claim in any other status, or one dated inside a closed period.
204	     */
205	    @Transactional
206	    public Claim resettle(String sheetId, String user, Long id) {
207	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
208	        RollupService.Snapshot before = rollup.snapshot(sheetId);
209	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
210	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusRefusedException();
211	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
212	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
213	        refuseIfClosed(sheetId, claim.getDate());
214	        BigDecimal old = claim.getSettledDue();
215	        BigDecimal figure = LateCharge.withChargeAsOpen(claim, dueOf(sheetId, person, claim), sheets.today(sheetId),
216	                settings.latePctOn(sheetId, claim.getDate()), roundingOf(sheetId, claim));
217	        claim.setSettledDue(figure);
218	        logStatus(sheetId, user, person, claim);
219	        Claim saved = claims.saveAndFlush(claim);
220	        record("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
221	                " old=" + figureText(old) + " new=" + figureText(figure));
222	        rollup.recordChanges(sheetId, user, before);
223	        return saved;
224	    }
225	
226	    /** A fixed due as an audit line has it: two decimals, or n/a when none. */
227	    private static String figureText(BigDecimal due) {
228	        return due == null ? "n/a" : due.setScale(2).toPlainString();
229	    }
230	
231	    /**
232	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number
233	     * and date, loses any figure a statement bound it to (live again until its new person's next
234	     * statement), and is listed as its new person's newest claim. A SETTLED or VOID claim cannot move,
235	     * nor one dated inside a closed period, nor one dated after its new person's retirement date.
236	     */
237	    @Transactional
238	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
239	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
240	        RollupService.Snapshot before = rollup.snapshot(sheetId);
241	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
242	        ClaimStatus status = claim.getStatus();
243	        if (status != ClaimStatus.DRAFT && !status.isOpen()) throw new ClaimStatusRefusedException();
244	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
245	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
246	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
247	        if (from.getId().equals(to.getId())) throw new ClaimReassignRefusedException();
248	        refuseIfClosed(sheetId, claim.getDate());
249	        if (!to.mayClaimOn(claim.getDate())) throw new PersonRetiredException();
250	        claim.unstate();
251	        claim.moveTo(to.getId(), claims.nextListed());
252	        Claim saved = claims.saveAndFlush(claim);
253	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
254	                " from=" + from.getName() + " to=" + to.getName());
255	        rollup.recordChanges(sheetId, user, before);
256	        return saved;
257	    }
258	
259	    /**
260	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
261	     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a
262	     * claim that is not OPEN, a date not after today, or a claim dated inside a closed period.
263	     */
264	    @Transactional
265	    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
266	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
267	        RollupService.Snapshot before = rollup.snapshot(sheetId);
268	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
269	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
270	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferDateException();
271	        refuseIfClosed(sheetId, claim.getDate());
272	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
273	        claim.setDeferredUntil(until);
274	        Claim saved = claims.saveAndFlush(claim);
275	        record("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber(), " until=" + until);
276	        rollup.recordChanges(sheetId, user, before);
277	        return saved;
278	    }
279	
280	    /** The PENDING claim a steward approves or rejects; refused when not PENDING or not a steward. */
281	    private Claim pendingForSteward(String sheetId, String user, Long id) {
282	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
283	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusRefusedException();
284	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
285	        return claim;
286	    }
287	
288	    /**
289	     * Give an opened claim its number: the sheet's next, or while the sheet numbers by period, the next
290	     * within the period its date falls in (in no period: the next in the sheet's X sequence).
291	     */
292	    private void number(Sheet sheet, Claim claim) {
293	        if (!sheet.numbersByPeriod()) {
294	            claim.setNumber(sheet.nextClaimNumber());
295	            return;
296	        }
297	        String period = periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
298	                .filter(p -> p.contains(claim.getDate()))
299	                .map(Period::getName)
300	                .findFirst().orElse("");
301	        claim.setNumberWithin(period, claims.lastNumberWithin(sheet.getId(), period) + 1);
302	    }
303	
304	    /**
305	     * A claim's figure now: the due fixed when it was settled, else the due bound by its person's
306	     * last statement, else its live due; null when it has none.
307	     */
308	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
309	        if (claim.getSettledDue() != null) return claim.getSettledDue();
310	        if (claim.isBound()) return claim.getStatedDue();
311	        return dueOf(sheetId, person, claim);
312	    }
313	
314	    /**
315	     * A claim's due now: its figure, with the late charge on top while it is overdue; null when it
316	     * has none. A statement binds the figure, never the charge.
317	     */
318	    public BigDecimal chargedFigureOf(String sheetId, Person person, Claim claim) {
319	        BigDecimal figure = figureOf(sheetId, person, claim);
320	        if (claim.getSettledDue() != null) return figure;
321	        return LateCharge.withCharge(claim, figure, sheets.today(sheetId),
322	                settings.latePctOn(sheetId, claim.getDate()), roundingOf(sheetId, claim));
323	    }
324	
325	    /** How the claim's live figures round: by its date, or a correction's by its corrected claim's ({@link Rounding}). */
326	    private RoundingMode roundingOf(String sheetId, Claim claim) {
327	        LocalDate basis = Rounding.basisOf(claim,
328	                Rounding.datesByNumber(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())));
329	        return Rounding.of(basis, settings.policyDate(sheetId), sheets.today(sheetId));
330	    }
331	
332	    /**
333	     * A claim's live due: its amount times the rate on its date of its person's grade in force on it, rounded to
334	     * cents as {@link Rounding} has it, and at least the sheet's floor in force on its date unless a correction; null with no rate.
335	     */
336	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
337	        BigDecimal floor = claim.isCorrection() ? null : settings.floorOn(sheetId, claim.getDate());
338	        RoundingMode rounding = roundingOf(sheetId, claim);
339	        return rates.on(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
340	                .map(Rate::getPct)
341	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
342	                .map(due -> floor == null ? due : due.max(floor))
343	                .orElse(null);
344	    }
345	
346	    /** Log the status the claim now has: by the user on the sheet's today, with its due at this moment. */
347	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
348	        claim.logStatus(user.strip(), sheets.today(sheetId), chargedFigureOf(sheetId, person, claim));
349	    }
350	
351	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
352	        record(event, sheetId, user, person, claim, claim.getNumber(), "");
353	    }
354	
355	    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
356	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number,
357	            String extra) {
358	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
359	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
360	                + (number != null ? " number=" + number : "") + extra);
361	    }
362	
363	    /**
364	     * Refuse a correction that names no SETTLED claim of its person by number, and a claim that names
365	     * one but is not a correction.
366	     */
367	    private void refuseUnlessCorrects(String sheetId, Long personId, BigDecimal amount, String corrects) {
368	        if (amount.signum() >= 0) {
369	            if (corrects != null) throw new CorrectionRefusedException();
370	            return;
371	        }
372	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
373	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
374	        if (!settled) throw new CorrectionRefusedException();
375	    }
376	
377	    /** Whether a clerk settles a claim whose due is above the clerk limit; a due of n/a is within any. */
378	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
379	        if (settings.roleOf(sheetId, user) == Role.STEWARD) return false;
380	        BigDecimal limit = settings.clerkLimit(sheetId);
381	        return limit != null && due != null && due.compareTo(limit) > 0;
382	    }
383	
384	    /** Refuse a change to a claim dated inside a closed period; the caller holds the sheet's lock. */
385	    private void refuseIfClosed(String sheetId, LocalDate date) {
386	        if (periods.closedOn(sheetId, date)) throw new PeriodClosedException();
387	    }
388	
389	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
390	        return date != null ? date : sheets.today(sheetId);
391	    }
392	}
